def legal_text(lang: str = "de") -> str:
    """Deutsch ist maßgeblich; alle anderen Sprachen zeigen die englische Orientierungsfassung."""
    return (LEGAL_DE if lang == "de" else LEGAL_EN).strip()


def legal_hash(lang: str = "de") -> str:
    """Prüfsumme des maßgeblichen deutschen Textes (wird bei der Zustimmung mitgespeichert)."""
    return hashlib.sha256(LEGAL_DE.strip().encode("utf-8")).hexdigest()
